import { describe, expect, it } from 'vitest';
import { targets } from '../targets';
import { loadTokens } from '../tokens';
import { emitTailwindTheme } from './tailwindTheme';
import { emitTokensCss } from './tokensCss';

const BANNER =
  '/* Generated by @webatlas/theme from tokens.json. Do not edit; run npm run generate:theme. */';

describe('emitters', () => {
  const tokens = loadTokens();

  it('tokens.css declares every colour', () => {
    const css = emitTokensCss(tokens);
    const root = css.slice(css.indexOf(':root {'));
    expect(root).toContain('--wa-color-brand: #14532D;');
    expect(root).toContain('--wa-color-depth-4: #3F2E8C;');
    expect(css.match(/^\s*--wa-color-(?!dark-)/gm)?.length).toBe(Object.keys(tokens.color).length);
  });

  it('tokens.css carries units', () => {
    const css = emitTokensCss(tokens);
    expect(css).toContain('--wa-radius-md: 4px;');
    expect(css).toContain('--wa-text-num: 12.5px;');
    expect(css).toContain('--wa-motion-fast: 120ms;');
    expect(css).toContain('--wa-shadow-pop: 0 4px 12px rgb(20 27 45 / 12%);');
  });

  it('dark series are separate', () => {
    expect(emitTokensCss(tokens)).toContain('--wa-color-dark-series-1: #3F8FD0;');
  });

  it('tailwind theme uses Tailwind namespaces', () => {
    const css = emitTailwindTheme(tokens);
    expect(css.split('\n')[1]).toBe('@theme {');
    expect(css).toContain('--color-brand: #14532D;');
    expect(css).toContain('--radius-md: 4px;');
    expect(css).toContain('--font-ui: "Archivo", "Segoe UI", system-ui, sans-serif;');
    expect(css).toContain('--text-body: 13px;');
    expect(css).toContain('--shadow-pop: 0 4px 12px rgb(20 27 45 / 12%);');
  });

  it('output is deterministic and LF', () => {
    for (const emit of [emitTokensCss, emitTailwindTheme]) {
      const first = emit(tokens);
      expect(emit(tokens)).toBe(first);
      expect(first).not.toContain('\r');
      expect(first.endsWith('\n')).toBe(true);
      expect(first.endsWith('\n\n')).toBe(false);
    }
  });

  it('target ids and paths are unique', () => {
    expect(new Set(targets.map((t) => t.id)).size).toBe(targets.length);
    expect(new Set(targets.map((t) => t.path)).size).toBe(targets.length);
  });

  it('each file starts with a generated-file banner', () => {
    for (const target of targets) {
      expect(target.emit(tokens).split('\n')[0]).toBe(BANNER);
    }
  });
});
